import type { Conversation, UserProfile } from '../types/assistant';

const CONVERSATIONS_KEY = 'my_ai_conversations_v1';
const ACTIVE_ID_KEY = 'my_ai_active_conversation_v1';
const PROFILE_KEY = 'my_ai_profile_v1';
const THEME_KEY = 'my_ai_theme_v2';

export const DEFAULT_PROFILE: UserProfile = {
  name: '',
    role: '',
      responseStyle: 'balanced',
        memoryNotes: [],
        };

        export function loadConversations(): Conversation[] {
          try {
              const raw = localStorage.getItem(CONVERSATIONS_KEY);
                  if (!raw) return [];
                      const parsed = JSON.parse(raw);
                          return Array.isArray(parsed) ? parsed : [];
                            } catch {
                                return [];
                                  }
                                  }

                                  export function saveConversations(conversations: Conversation[]): void {
                                    try {
                                        // Strip ephemeral object preview URLs and trim huge inline image payloads if storage quota is tight
                                            const serializable = conversations.map((conv) => ({
                                                  ...conv,
                                                        messages: conv.messages.map((msg) => ({
                                                                ...msg,
                                                                        attachments: msg.attachments?.map((att) => ({
                                                                                  ...att,
                                                                                            previewUrl: att.kind === 'image' ? `data:${att.mimeType};base64,${att.data}` : undefined,
                                                                                                    })),
                                                                                                          })),
                                                                                                              }));
                                                                                                                  localStorage.setItem(CONVERSATIONS_KEY, JSON.stringify(serializable));
                                                                                                                    } catch {
                                                                                                                        // Fallback: store conversations without base64 image blobs if localStorage quota exceeded
                                                                                                                            try {
                                                                                                                                  const lightweight = conversations.map((conv) => ({
                                                                                                                                          ...conv,
                                                                                                                                                  messages: conv.messages.map((msg) => ({
                                                                                                                                                            ...msg,
                                                                                                                                                                      attachments: msg.attachments?.map((att) => ({
                                                                                                                                                                                  ...att,
                                                                                                                                                                                              data: att.kind === 'image' ? '' : att.data.slice(0, 4000),
                                                                                                                                                                                                          previewUrl: undefined,
                                                                                                                                                                                                                    })),
                                                                                                                                                                                                                            })),
                                                                                                                                                                                                                                  }));
                                                                                                                                                                                                                                        localStorage.setItem(CONVERSATIONS_KEY, JSON.stringify(lightweight));
                                                                                                                                                                                                                                            } catch {
                                                                                                                                                                                                                                                  // Ignore storage failures silently
                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        export function loadActiveConversationId(): string | null {
                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                              return localStorage.getItem(ACTIVE_ID_KEY);
                                                                                                                                                                                                                                                                } catch {
                                                                                                                                                                                                                                                                    return null;
                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                      export function saveActiveConversationId(id: string | null): void {
                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                            if (id) {
                                                                                                                                                                                                                                                                                  localStorage.setItem(ACTIVE_ID_KEY, id);
                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                            localStorage.removeItem(ACTIVE_ID_KEY);
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                  } catch {
                                                                                                                                                                                                                                                                                                      // Ignore storage errors
                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                        export function loadProfile(): UserProfile {
                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                              const raw = localStorage.getItem(PROFILE_KEY);
                                                                                                                                                                                                                                                                                                                  if (!raw) return DEFAULT_PROFILE;
                                                                                                                                                                                                                                                                                                                      const parsed = JSON.parse(raw) as Partial<UserProfile>;
                                                                                                                                                                                                                                                                                                                          return {
                                                                                                                                                                                                                                                                                                                                name: typeof parsed.name === 'string' ? parsed.name : '',
                                                                                                                                                                                                                                                                                                                                      role: typeof parsed.role === 'string' ? parsed.role : '',
                                                                                                                                                                                                                                                                                                                                            responseStyle:
                                                                                                                                                                                                                                                                                                                                                    parsed.responseStyle === 'concise' ||
                                                                                                                                                                                                                                                                                                                                                            parsed.responseStyle === 'detailed' ||
                                                                                                                                                                                                                                                                                                                                                                    parsed.responseStyle === 'balanced'
                                                                                                                                                                                                                                                                                                                                                                              ? parsed.responseStyle
                                                                                                                                                                                                                                                                                                                                                                                        : 'balanced',
                                                                                                                                                                                                                                                                                                                                                                                              memoryNotes: Array.isArray(parsed.memoryNotes) ? parsed.memoryNotes : [],
                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                    } catch {
                                                                                                                                                                                                                                                                                                                                                                                                        return DEFAULT_PROFILE;
                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                          export function saveProfile(profile: UserProfile): void {
                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                localStorage.setItem(PROFILE_KEY, JSON.stringify(profile));
                                                                                                                                                                                                                                                                                                                                                                                                                  } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                      // Ignore storage errors
                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                        export function loadTheme(): 'light' | 'dark' {
                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                              const stored = localStorage.getItem(THEME_KEY);
                                                                                                                                                                                                                                                                                                                                                                                                                                  if (stored === 'dark' || stored === 'light') return stored;
                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                    return 'light';
                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          return 'light';
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            export function saveTheme(theme: 'light' | 'dark'): void {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  localStorage.setItem(THEME_KEY, theme);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Ignore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export function exportConversationAsMarkdown(conversation: Conversation): void {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const lines: string[] = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `# ${conversation.title}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `Mode: ${conversation.mode} · Exported ${new Date().toLocaleString()}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '---',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (const msg of conversation.messages) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const speaker = msg.role === 'user' ? 'You' : 'My AI';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const time = new Date(msg.createdAt).toLocaleTimeString([], {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  hour: '2-digit',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        minute: '2-digit',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                lines.push(`### ${speaker} (${time})`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (msg.attachments && msg.attachments.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          lines.push(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  `Attachments: ${msg.attachments.map((a) => a.name).join(', ')}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              lines.push('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      lines.push(msg.content);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          lines.push('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const blob = new Blob([lines.join('\n')], { type: 'text/markdown;charset=utf-8' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const url = URL.createObjectURL(blob);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const anchor = document.createElement('a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const safeName = conversation.title
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .replace(/[^a-z0-9]+/g, '-')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .replace(/^-|-$/g, '') || 'conversation';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  anchor.href = url;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    anchor.download = `${safeName}.md`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.body.appendChild(anchor);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        anchor.click();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.body.removeChild(anchor);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            URL.revokeObjectURL(url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }